package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class Load056Test {
 static JSONObject input(WorldLedger worlds,String preset,double span,double x)throws Exception{var scene=SpatialScene.parse(Construction054.kit(new JSONObject().put("preset",preset).put("spanM",span)).toString(),UUID.randomUUID().toString());var w=worlds.create(scene,"LABELLED056 load redesign");var in=worlds.observe(w.getString("id"));var out=new JSONObject();for(String k:List.of("worldId","expectedRevision","expectedHash"))out.put(k,in.get(k));return out.put("construction051",Construction051.options(new JSONObject().put("centerX",x))).put("forceLimitN",40).put("torqueLimitNm",4);}
 @Test public void frozenOriginalAndWiderLayoutsEarnActualEccentricLoadEvidence()throws Exception{
  Path root=Files.createTempDirectory("load056-matrix-");var worlds=new WorldLedger(root);var in=input(worlds,"wide",1,0);var before=worlds.observe(in.getString("worldId"));var source=worlds.source(before);var candidates=Design056.proposals(source,worlds.preview(in));var rows=new JSONArray();var errors=new ArrayList<String>();System.out.println("LOAD056_MATRIX "+root);
  for(Object raw:candidates){var c=(JSONObject)raw;var row=new JSONObject().put("candidate",c.getString("id")).put("plan",c.getJSONObject("plan"));rows.put(row);try{var run=Construction054Test.nativeRun(root.resolve(c.getString("id")),source,c.getJSONObject("plan"));row.put("assembly",WorldReport.packed(run));assertTrue(WorldVerify.verify(run).getBoolean("passed"));assertTrue(Construction051.verifyStructure(run).getBoolean("passed"));var loads=Load056.evaluate(root.resolve("loads"),run,24,()->false);row.put("loads",loads).put("originalLoads",Load056.original(root.resolve("loads"),run,24));assertTrue(loads.getBoolean("complete"));row.put("passed",true);}catch(Throwable error){row.put("passed",false).put("error",error.toString());errors.add(c.getString("id")+": "+error);}finally{Files.writeString(root.resolve("results.json"),new JSONObject().put("results",rows).toString());}}
  assertTrue(before.similar(worlds.observe(in.getString("worldId"))));assertTrue(errors.toString(),errors.isEmpty());assertFalse("Original narrow spacing must retain actual requested-load failure",rows.getJSONObject(0).getJSONObject("loads").getBoolean("qualifies"));assertTrue("At least one bounded wider layout must earn requested load",rows.getJSONObject(1).getJSONObject("loads").getBoolean("qualifies")||rows.getJSONObject(2).getJSONObject("loads").getBoolean("qualifies"));
 }
 @Test public void requestedLoadsAndSpanAreStrictlyBounded()throws Exception{assertEquals(24,Load056.required(new JSONObject()));assertThrows(IllegalArgumentException.class,()->Load056.required(new JSONObject().put("requiredLoadN",20)));assertThrows(IllegalArgumentException.class,()->Load056.required(new JSONObject().put("requiredLoadN","24")));var root=Files.createTempDirectory("load056-bounds-");var worlds=new WorldLedger(root);var in=input(worlds,"compact",1,0);in.getJSONObject("construction051").put("supportSpanM",1.4);assertThrows(IllegalArgumentException.class,()->worlds.preview(in));}
}
